import{_ as a,o as r,c as e,a2 as o}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"مبدأ التوازن بين الفرد والجماعة","description":"","frontmatter":{},"headers":[],"relativePath":"ar/0026-个体与集体平衡原理.md","filePath":"ar/0026-个体与集体平衡原理.md"}'),l={name:"ar/0026-个体与集体平衡原理.md"};function d(i,t,n,h,s,_){return r(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="مبدأ-التوازن-بين-الفرد-والجماعة" tabindex="-1">مبدأ التوازن بين الفرد والجماعة <a class="header-anchor" href="#مبدأ-التوازن-بين-الفرد-والجماعة" aria-label="Permalink to &quot;مبدأ التوازن بين الفرد والجماعة&quot;">​</a></h1><table tabindex="0"><thead><tr><th>العنصر</th><th>المحتوى</th></tr></thead><tbody><tr><td>رقم الوثيقة</td><td>26</td></tr><tr><td>الوحدة</td><td>آلية المراسي ومبادئ التكافل</td></tr><tr><td>الكلمات المفتاحية</td><td>الفرد والجماعة، مبدأ التوازن، الحقوق والواجبات، الأخلاق التكافلية، التعديل الديناميكي</td></tr></tbody></table><h2 id="أولاً-السؤال-الأساسي-للفرد-والجماعة" tabindex="-1">أولاً: السؤال الأساسي للفرد والجماعة <a class="header-anchor" href="#أولاً-السؤال-الأساسي-للفرد-والجماعة" aria-label="Permalink to &quot;أولاً: السؤال الأساسي للفرد والجماعة&quot;">​</a></h2><p>كيفية معالجة العلاقة بين الفرد والجماعة من أكثر أسئلة أي حضارة جوهرية. كان جواب عصر النظام الافتراسي: الجماعة موجودة للفرد، والقوي يأكل الضعيف؛ والضعفاء مجرد أحجار خطى لصعود الأقوياء. قاد هذا الجواب في النهاية إلى إفراغ الحضارة وانهيارها. أما حضارة التكافل المرساة فتعطي جواباً جديداً كلياً: الفرد والجماعة يعزز أحدهما الآخر ويكمل أحدهما الآخر؛ الجماعة تربة تغذي الأفراد، والأفراد أزهار تتفتح على تربة الجماعة. فقط حين يتطور الاثنان معاً ويتكاملان معاً، تبلغ الحضارة ازدهاراً أبدياً حقاً.</p><p>هذا الجواب ليس مثالية عاطفية، بل قائم على استدلالات صارمة من قوانين كون الأصل. في هينغ يوانتشو، ينص قانون حفظ الطاقة على أن الطاقة لا تُخلق ولا تُفنى، بل تتحول وتنتقل فحسب. علاقة الفرد والجماعة تتبع القانون نفسه: يساهم الأفراد بالطاقة للجماعة، وترد الجماعة الطاقة للأفراد؛ هذا التدفق قد يكون دوراناً إيجابياً أو سلبياً. في الدوران الإيجابي، كلما أعطى الفرد أكثر أخذ أكثر؛ وفي السلبي، كلما أخذ الفرد أكثر نال أقل. مهمة الحضارة التكافلية بناء آلية الدوران الإيجابي والحفاظ عليها.</p><p>يتلخص جوهر مبدأ التوازن بين الفرد والجماعة في ثلاث جمل:</p><ol><li><strong>الفرد غاية لا وسيلة</strong>: كل كائن غاية بذاته؛ الجماعة موجودة لخدمة نمو كل فرد، لا العكس</li><li><strong>الجماعة أساس لا تبعية</strong>: بلا جماعة، يفقد الأفراد تربة النمو؛ تطور الأفراد لا ينفصل عن سند الجماعة</li><li><strong>المساهمة والرد متناسبان</strong>: حصول الفرد على سند الجماعة متناسب مع مساهمته فيها؛ «من عمل أكثر نال أكثر» و«طريق لكل إنسان» كلاهما مضمون</li></ol><h2 id="ثانياً-نموذج-التوازن-الديناميكي-بين-الفرد-والجماعة" tabindex="-1">ثانياً: نموذج التوازن الديناميكي بين الفرد والجماعة <a class="header-anchor" href="#ثانياً-نموذج-التوازن-الديناميكي-بين-الفرد-والجماعة" aria-label="Permalink to &quot;ثانياً: نموذج التوازن الديناميكي بين الفرد والجماعة&quot;">​</a></h2><p>علاقة الفرد والجماعة ليست نسبة ثابتة ساكنة، بل عملية توازن ديناميكي. تحقق الشبكة التكافلية هذا التوازن عبر منظومة «ثلاثة نوى وحلقتان»:</p><table tabindex="0"><thead><tr><th>بُعد التوازن</th><th>الآلية المركزية</th><th>هدف التوازن</th><th>المؤشر النموذجي</th></tr></thead><tbody><tr><td>بُعد الطاقة</td><td>تجميع برك الطاقة وردها</td><td>مساهمة كل كائن وعائده متوازنان</td><td>مؤشر المساهمة / مؤشر العائد</td></tr><tr><td>بُعد النمو</td><td>ملاءمة الأنظمة والإرشاد</td><td>ينمو كل كائن في طريق يناسبه</td><td>سرعة النمو / ملاءمة النظام</td></tr><tr><td>بُعد الموارد</td><td>نظام العقود المرتبطة بالإنتاج</td><td>تناسب حيازة الموارد مع المساهمة</td><td>الحيازة / قيمة المساهمة</td></tr><tr><td>بُعد المسؤولية</td><td>منظومة حقول المسؤولية</td><td>يحمل كل كائن نصيباً من المسؤولية العامة</td><td>مؤشر حقل المسؤولية</td></tr><tr><td>بُعد القرار</td><td>المداولة الديمقراطية</td><td>إرادة الفرد ومصلحة الجماعة معاً</td><td>معدل المشاركة / معدل التمثيل</td></tr></tbody></table><h3 id="_2-1-توازن-بُعد-الطاقة" tabindex="-1">2.1 توازن بُعد الطاقة <a class="header-anchor" href="#_2-1-توازن-بُعد-الطاقة" aria-label="Permalink to &quot;2.1 توازن بُعد الطاقة&quot;">​</a></h3><p>أبعد بُعد جوهرية. يساهم كل كائن بالطاقة في البرك الجماعية عبر الزراعة والعمل؛ وترد الجماعة الطاقة لكل كائن بنسبة مساهمته عبر شبكة المراسي. دورة «المساهمة — الرد» هذه تضمن عدالة توزيع الطاقة وتحفظ في الوقت نفسه ازدهار الطاقة العام للجماعة.</p><p>يتبع توازن بُعد الطاقة «مبدأ الرد المتناسب»: كلما زادت مساهمة الكائن زاد ما يحصل عليه؛ لكن الرد لا يكون صفراً لأحد أبداً — حتى الكائنات العاجزة مؤقتاً (كالمسنين والأطفال والمرضى وذوي الإعاقة) تنال طاقة حماية أساسية من الجماعة. هذه هي ضمانة «طريق لكل إنسان».</p><h3 id="_2-2-توازن-بُعد-النمو" tabindex="-1">2.2 توازن بُعد النمو <a class="header-anchor" href="#_2-2-توازن-بُعد-النمو" aria-label="Permalink to &quot;2.2 توازن بُعد النمو&quot;">​</a></h3><p>يضمن توازن بُعد النمو أن يجد كل كائن طريقاً تنموياً يناسبه. تغطي الأنظمة الأصلية الثلاثمائة استعدادات واهتمامات مختلفة؛ وبملاءمة نواة المعلومات وإرشادها، يستطيع كل كائن اختيار أنسب طرق الزراعة.</p><p>يؤكد توازن بُعد النمو على «الملاءمة لا التماثل»: سرعات ومسارات نمو الكائنات المختلفة مختلفة، وهذا أمر طبيعي يستحق الاحترام. لا تطلب الشبكة أن تنمو كل الكائنات بالسرعة نفسها، لكنها تضمن أن تتمكن كل الكائنات من النمو.</p><h3 id="_2-3-توازن-بُعد-الموارد" tabindex="-1">2.3 توازن بُعد الموارد <a class="header-anchor" href="#_2-3-توازن-بُعد-الموارد" aria-label="Permalink to &quot;2.3 توازن بُعد الموارد&quot;">​</a></h3><p>يضمن توازن بُعد الموارد عدالة توزيع الموارد. بنظام العقود المرتبطة بالإنتاج، ترتبط حيازة كل كائن من الموارد بمساهمته الإنتاجية؛ من عمل أكثر نال أكثر، ومن ساهم أكثر نال أكثر. في الوقت نفسه، تضمن منظومة الضمان الأساسي أن لكل إنسان حقلاً للمسؤولية، مانعة حالة «من لا شيء له يخسر كل شيء».</p><h3 id="_2-4-توازن-بُعد-المسؤولية" tabindex="-1">2.4 توازن بُعد المسؤولية <a class="header-anchor" href="#_2-4-توازن-بُعد-المسؤولية" aria-label="Permalink to &quot;2.4 توازن بُعد المسؤولية&quot;">​</a></h3><p>يضمن توازن بُعد المسؤولية استدامة الجماعة. يحمل كل كائن نصيباً معيناً من المسؤولية العامة: صيانة المراسي، والمشاركة في بناء الشبكة التكافلية، ونقل خبرات الزراعة، إلخ. تجعل منظومة حقول المسؤولية هذه المسؤوليات كمية، صريحة، قابلة للقياس والتقييم.</p><h3 id="_2-5-توازن-بُعد-القرار" tabindex="-1">2.5 توازن بُعد القرار <a class="header-anchor" href="#_2-5-توازن-بُعد-القرار" aria-label="Permalink to &quot;2.5 توازن بُعد القرار&quot;">​</a></h3><p>يضمن توازن بُعد القرار التعبير عن إرادة الفرد وصواب قرارات الجماعة. تمر قرارات الحضارة الكبرى بآليات المداولة الديمقراطية، حيث لكل كائن حق إبداء الرأي؛ وفي الوقت نفسه، تجري المؤسسات المتخصصة التقييم التقني وضبط المخاطر، مانعة أخطاء القرار الناجمة عن عدم تماثل المعلومات.</p><h2 id="ثالثاً-حماية-حقوق-الفرد-ومصالح-الجماعة" tabindex="-1">ثالثاً: حماية حقوق الفرد ومصالح الجماعة <a class="header-anchor" href="#ثالثاً-حماية-حقوق-الفرد-ومصالح-الجماعة" aria-label="Permalink to &quot;ثالثاً: حماية حقوق الفرد ومصالح الجماعة&quot;">​</a></h2><p>يتطلب التوازن بين الفرد والجماعة حماية حقوق الأفراد والحفاظ على مصالح الجماعة معاً. تؤسس الحضارة التكافلية آلية ضمان مزدوجة:</p><h3 id="_3-1-منظومة-حماية-حقوق-الفرد" tabindex="-1">3.1 منظومة حماية حقوق الفرد <a class="header-anchor" href="#_3-1-منظومة-حماية-حقوق-الفرد" aria-label="Permalink to &quot;3.1 منظومة حماية حقوق الفرد&quot;">​</a></h3><ol><li><strong>حق الحياة</strong>: لكل كائن حق البقاء المصون؛ تقدم الجماعة ضمانات الحياة الأساسية</li><li><strong>حق الزراعة</strong>: لكل كائن حق اختيار طريق زراعة يناسبه؛ لا يحق لأحد حرمان غيره من فرصة الزراعة</li><li><strong>حق الخصوصية</strong>: تجمع الشبكة بيانات التطور فقط، لا معلومات الأفراد الخاصة؛ لكل كائن حق إخفاء أسراره</li><li><strong>حق الانسحاب</strong>: ضمن الإجراءات القانونية، يستطيع الكائن طلب تعديل علاقته التكافلية؛ التكافل الإجباري غير جائز</li><li><strong>حق الاستئناف</strong>: حين يرى الأفراد أن حقوقهم انتهكت، يستطيعون الاستئناف لدى هيئات التحكيم في جميع المستويات</li></ol><h3 id="_3-2-منظومة-الحفاظ-على-مصالح-الجماعة" tabindex="-1">3.2 منظومة الحفاظ على مصالح الجماعة <a class="header-anchor" href="#_3-2-منظومة-الحفاظ-على-مصالح-الجماعة" aria-label="Permalink to &quot;3.2 منظومة الحفاظ على مصالح الجماعة&quot;">​</a></h3><ol><li><strong>أمن الشبكة التكافلية</strong>: كل فعل يضر شبكة المراسي جريمة خطيرة؛ على الجماعة اتخاذ الإجراءات اللازمة لحماية البنية المشتركة</li><li><strong>الوفاء بالمسؤوليات العامة</strong>: يجب على كل كائن الوفاء بنصيبه من المسؤولية العامة؛ ورفض الوفاء يقابل بتنظيم مماثل</li><li><strong>الحفاظ على نظام الطاقة</strong>: سرقة الطاقة والمنافسة غير العادلة ممنوعتان منعاً باتاً؛ تحفظ الجماعة نظام طاقة عادلاً عبر المنظومة القانونية</li><li><strong>الاستجابة للأزمات</strong>: عند الأزمات الكونية (كغزو الأبعاد، وشذوذ القوانين)، يحق للجماعة تعبئة كل الكائنات للاستجابة</li></ol><h3 id="_3-3-العلاقة-بين-المنظومتين" tabindex="-1">3.3 العلاقة بين المنظومتين <a class="header-anchor" href="#_3-3-العلاقة-بين-المنظومتين" aria-label="Permalink to &quot;3.3 العلاقة بين المنظومتين&quot;">​</a></h3><p>منظومة حماية حقوق الفرد ومنظومة الحفاظ على مصالح الجماعة ليستا متضادتين بل متكاملتين. الغرض من حماية حقوق الأفراد حماية أساس الجماعة — فالجماعة التي تدوس الأفراد لا تطول؛ والغرض من الحفاظ على مصالح الجماعة حماية بيئة نمو الأفراد — فالأفراد بلا حماية جماعية ضعفاء.</p><p>عند تعارضهما، تتبنى الحضارة مبدأ «أولوية الإجراءات»: حل التعارض يجب أن يمر بالإجراءات القانونية والمداولة الديمقراطية، لا بقرارات القوة أو السلطة التعسفية. في الغالبية العظمى من الحالات، حماية حقوق الأفراد والحفاظ على مصالح الجماعة ليسا في تعارض حقيقي؛ عادة ما ينشأ التعارض من سوء فهم المعلومات أو فشل المؤسسات، ويمكن حله بآليات شفافة.</p><h2 id="رابعاً-آلية-التعديل-الديناميكي" tabindex="-1">رابعاً: آلية التعديل الديناميكي <a class="header-anchor" href="#رابعاً-آلية-التعديل-الديناميكي" aria-label="Permalink to &quot;رابعاً: آلية التعديل الديناميكي&quot;">​</a></h2><p>توازن الفرد والجماعة ليس صيغة ثابتة، بل يتطلب تعديلاً ديناميكياً حسب الواقع. تعدل الشبكة التكافلية التوازن عبر آلية دورة التغذية الراجعة:</p><ol><li><strong>تعديل مرحلة التطور</strong>: في مرحلة بناء الحضارة المبكرة، يميل التوازن على النحو المناسب نحو الجماعة، مركّزاً الموارد لبناء المراسي؛ وفي مرحلة النضج، يميل نحو الأفراد، رافعاً استقلالهم الذاتي</li><li><strong>تعديل حالة الأزمة</strong>: في حالات الأزمة الكونية، يميل التوازن مؤقتاً نحو الجماعة، محشداً الموارد للاستجابة؛ وبعد انتهاء الأزمة يعود تلقائياً</li><li><strong>تعديل الفروق الإقليمية</strong>: تختلف أوضاع الموارد ومستويات التطور بين المناطق النجمية والأبعاد؛ تعدل نسبة التوازن حسب الظروف المحلية</li><li><strong>تعديل الفروق الفردية</strong>: تختلف أساليب التوازن بين الأفراد بحسب مراحل نموهم ومستويات مساهمتهم؛ الصغار والكبار، الأقوياء والضعفاء — معاملة مختلفة لكن عادلة</li></ol><p>تتم جميع التعديلات عبر إجراءات مؤسسية شفافة، وكل تعديل يجب أن يمر بتبرير وإشراف، مانعاً إساءة استعمال السلطة تحت شعار «مصالح الجماعة».</p><h2 id="الخاتمة" tabindex="-1">الخاتمة <a class="header-anchor" href="#الخاتمة" aria-label="Permalink to &quot;الخاتمة&quot;">​</a></h2><p>مبدأ التوازن بين الفرد والجماعة هو المبدأ القيمي الأكثر جوهرية لحضارة التكافل المرساة. يتجاوز نقيضي «الفردية» و«الجماعية»، مؤسساً آلية توازن ديناميكية يتغذى فيها الفرد والجماعة على بعضهما ويحققان الازدهار المشترك. هذا المبدأ ليس أساس الحكم الاجتماعي فحسب، بل هو الأساس القيمي لمنظومة الزراعة: بهذا التوازن، يستطيع كل كائن أن ينال قوة النمو من الجماعة ويرد إليها، مشكلاً دورة كبرى عادلة وكفؤة معاً، تقود الحضارة التكافلية كلها نحو الازدهار الأبدي.</p><h2 id="الوثائق-ذات-الصلة" tabindex="-1">الوثائق ذات الصلة <a class="header-anchor" href="#الوثائق-ذات-الصلة" aria-label="Permalink to &quot;الوثائق ذات الصلة&quot;">​</a></h2><ul><li>03-共生文明宪章 (ميثاق الحضارة التكافلية)</li><li>06-多劳多得分配原理 (مبدأ توزيع «من عمل أكثر نال أكثر»)</li><li>08-人人有路保障体系 (منظومة ضمان «طريق لكل إنسان»)</li></ul>',39)])])}const b=a(l,[["render",d]]);export{c as __pageData,b as default};
